BEGIN;
CREATE TABLE app.quote_draft (id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,current_revision_id uuid,revision integer NOT NULL DEFAULT 0 CHECK(revision>=0),created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),updated_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,job_id),UNIQUE(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id) REFERENCES app.job(tenant_id,id));
CREATE TABLE app.quote_revision (id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,quote_draft_id uuid NOT NULL,revision integer NOT NULL CHECK(revision>0),previous_revision_id uuid,currency char(3) NOT NULL CHECK(currency='GBP'),tax_policy_version varchar(80) NOT NULL,subtotal_pence bigint NOT NULL CHECK(subtotal_pence>=0),discount_pence bigint NOT NULL CHECK(discount_pence>=0),net_pence bigint NOT NULL CHECK(net_pence>=0),tax_pence bigint NOT NULL CHECK(tax_pence>=0),total_pence bigint NOT NULL CHECK(total_pence>=0),issuable boolean NOT NULL,blockers jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,quote_draft_id,revision),UNIQUE(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,quote_draft_id) REFERENCES app.quote_draft(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,previous_revision_id) REFERENCES app.quote_revision(tenant_id,job_id,id),CHECK(previous_revision_id IS NULL OR previous_revision_id<>id),CHECK(subtotal_pence-discount_pence=net_pence),CHECK(net_pence+tax_pence=total_pence));
ALTER TABLE app.quote_draft ADD CONSTRAINT quote_draft_current_revision_fk FOREIGN KEY(tenant_id,job_id,current_revision_id) REFERENCES app.quote_revision(tenant_id,job_id,id);
CREATE TABLE app.quote_line (id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,quote_revision_id uuid NOT NULL,scope_item_id uuid NOT NULL,scope_revision_id uuid NOT NULL,origin varchar(10) NOT NULL CHECK(origin IN('captured','human')),description varchar(500) NOT NULL,included boolean NOT NULL,exclusion_reason varchar(200),quantity_decimal varchar(40),unit varchar(40),unit_rate_pence bigint CHECK(unit_rate_pence>=0),discount_decimal varchar(20) NOT NULL,tax_treatment varchar(40) NOT NULL,rate_provenance varchar(24) CHECK(rate_provenance IN('entered','suggestion_accepted')),category varchar(100),region varchar(100),ordinal integer NOT NULL CHECK(ordinal>0),created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,quote_revision_id,scope_item_id),FOREIGN KEY(tenant_id,job_id,quote_revision_id) REFERENCES app.quote_revision(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,scope_item_id) REFERENCES app.scope_identity(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,scope_revision_id) REFERENCES app.scope_revision(tenant_id,job_id,id),CHECK(included OR exclusion_reason IS NOT NULL));
CREATE TABLE app.rate_book_observation (id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,scope_item_id uuid NOT NULL,source_scope_revision_id uuid NOT NULL,unit varchar(40) NOT NULL,rate_principal_pence bigint NOT NULL CHECK(rate_principal_pence>=0),currency char(3) NOT NULL CHECK(currency='GBP'),tax_basis varchar(40) NOT NULL,category varchar(100),region varchar(100),effective_at timestamptz NOT NULL,provenance varchar(24) NOT NULL CHECK(provenance IN('entered','suggestion_accepted')),created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,source_scope_revision_id,unit,rate_principal_pence,tax_basis),FOREIGN KEY(tenant_id,job_id,scope_item_id) REFERENCES app.scope_identity(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,source_scope_revision_id) REFERENCES app.scope_revision(tenant_id,job_id,id));
CREATE TRIGGER quote_revision_immutable BEFORE UPDATE OR DELETE ON app.quote_revision FOR EACH ROW EXECUTE FUNCTION app.reject_immutable_commercial_mutation();
CREATE TRIGGER quote_line_immutable BEFORE UPDATE OR DELETE ON app.quote_line FOR EACH ROW EXECUTE FUNCTION app.reject_immutable_commercial_mutation();
CREATE TRIGGER rate_book_observation_immutable BEFORE UPDATE OR DELETE ON app.rate_book_observation FOR EACH ROW EXECUTE FUNCTION app.reject_immutable_commercial_mutation();
DO $$ DECLARE n text; BEGIN FOREACH n IN ARRAY ARRAY['quote_draft','quote_revision','quote_line','rate_book_observation'] LOOP EXECUTE format('ALTER TABLE app.%I OWNER TO jobguard_migration',n);EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('ALTER TABLE app.%I FORCE ROW LEVEL SECURITY',n);EXECUTE format('CREATE POLICY tenant_isolation ON app.%I FOR ALL TO jobguard_runtime,jobguard_migration USING (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',n);EXECUTE format('GRANT SELECT,INSERT ON app.%I TO jobguard_runtime',n);EXECUTE format('REVOKE UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER ON app.%I FROM jobguard_runtime',n);END LOOP;END $$;
GRANT UPDATE(current_revision_id,revision,updated_at) ON app.quote_draft TO jobguard_runtime;
COMMIT;
